import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement from spec
  group.position.set(0, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create plane geometry (512:320 aspect ratio = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Load brushed metal texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipmapLinearFilter;

  // Create material for static composition
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    color: new THREE.Color(0xe8ecf2),
  });

  // Create and add mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Setup cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // No event handlers (static card, no interactivity)
  group.userData.handlers = {};

  return group;
}
